import {
  Body,
  Button,
  Container,
  Head as EmailHead,
  Html,
  Img,
  Preview,
  Section,
  Text,
  Heading,
  Link,
} from "jsx-email";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type ImageGridHero_HeroWithImageGridVariant =
  | "images-bottom"
  | "images-top"
  | "offset-images-bottom"
  | "offset-images-top";

interface ImageGridHero_HeroWithImageGridImage {
  alt: string;
  src: string;
}

interface ImageGridHero_HeroWithImageGridProps {
  theme?: EmailTheme;
  eyebrow?: string;
  heading?: string;
  subheading?: string;
  description?: string;
  ctaLabel?: string;
  ctaHref?: string;
  images?: ImageGridHero_HeroWithImageGridImage[];
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  buttonBackgroundColor?: string;
  buttonTextColor?: string;
  variant?: ImageGridHero_HeroWithImageGridVariant;
}

const ImageGridHero_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const ImageGridHero_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .hero-image-grid-container {
        width: 100% !important;
      }

      .hero-image-grid-heading {
        font-size: 36px !important;
        line-height: 40px !important;
      }

      .hero-image-grid-image {
        margin: 0 12px 24px !important;
        max-width: 96px !important;
      }

      .hero-image-grid-gap {
        display: none !important;
      }
    }
  `;

const ImageGridHero_regularImages: ImageGridHero_HeroWithImageGridImage[] =
  Array.from({ length: 7 }, (_, index) => ({
    alt: `Image ${index + 1}`,
    src: emailAsset(`hero/mosaic-${index + 1}.jpg`),
  }));

const ImageGridHero_offsetImageNumbers = [1, 2, 7, 10, 4, 6, 8, 9, 5, 11];

const ImageGridHero_offsetImages: ImageGridHero_HeroWithImageGridImage[] =
  ImageGridHero_offsetImageNumbers.map((imageNumber, index) => ({
    alt: `Image ${index + 1}`,
    src: emailAsset(`hero/mosaic-${imageNumber}.jpg`),
  }));

const ImageGridHero_Spacer = ({ height }: { height: number }) => (
  <Section style={{ fontSize: 0, height, lineHeight: `${height}px` }}>
    &zwj;
  </Section>
);

const ImageGridHero_ImageGallery = ({
  images,
  offset,
}: {
  images: ImageGridHero_HeroWithImageGridImage[];
  offset: boolean;
}) => {
  const defaults = offset
    ? ImageGridHero_offsetImages
    : ImageGridHero_regularImages;
  const resolvedImages = defaults.map((fallback, index) =>
    images[index] ? { ...fallback, ...images[index] } : fallback
  );
  const imageWidth = offset ? 91 : 120;
  const wrapAfter = offset ? 4 : 3;
  return (
    <Section style={{ fontSize: 0, textAlign: "center" }}>
      {resolvedImages.map((image, index) => (
        <span key={`${image.src}-${index}`}>
          <Img
            alt={image.alt}
            className="hero-image-grid-image"
            src={image.src}
            width={imageWidth}
            style={{
              borderRadius: "4px",
              display: "inline-block",
              marginBottom: "48px",
              marginTop: offset && index % 2 === 0 ? "24px" : 0,
              maxWidth: "100%",
              verticalAlign: "middle",
            }}
          />
          {index < resolvedImages.length - 1 && index !== wrapAfter ? (
            <span
              className="hero-image-grid-gap"
              style={{ display: "inline-block", width: "24px" }}
            >
              &nbsp;
            </span>
          ) : null}
        </span>
      ))}
    </Section>
  );
};

type ImageGridHero_SectionProps = Required<
  Omit<ImageGridHero_HeroWithImageGridProps, "theme" | "variant">
> & {
  variant: ImageGridHero_HeroWithImageGridVariant;
};

const ImageGridHero_HeroWithImageGridSection = ({
  backgroundColor,
  buttonBackgroundColor,
  buttonTextColor,
  ctaHref,
  ctaLabel,
  description,
  eyebrow,
  heading,
  images,
  logoAlt,
  logoHref,
  logoSrc,
  subheading,
  variant,
}: ImageGridHero_SectionProps) => {
  const imagesFirst = variant.endsWith("-top");
  const offset = variant.startsWith("offset-");
  const gallery = (
    <ImageGridHero_ImageGallery images={images} offset={offset} />
  );
  const content = (
    <Section style={{ padding: "0 24px", textAlign: "center" }}>
      <ImageGridHero_Spacer height={imagesFirst ? 20 : 44} />
      <Text
        style={{
          color: "#030712",
          fontFamily: ImageGridHero_fontFamily,
          fontSize: "16px",
          fontWeight: 200,
          lineHeight: "24px",
          margin: 0,
        }}
      >
        {eyebrow}
      </Text>
      <Heading
        className="hero-image-grid-heading"
        style={{
          color: "#030712",
          fontFamily: ImageGridHero_fontFamily,
          fontSize: "48px",
          fontWeight: 500,
          lineHeight: "58px",
          margin: 0,
        }}
        as="h1"
      >
        {heading}
      </Heading>
      <Text
        style={{
          color: "#030712",
          fontFamily: ImageGridHero_fontFamily,
          fontSize: "18px",
          lineHeight: "28px",
          margin: 0,
        }}
      >
        {subheading}
      </Text>
      <Text
        style={{
          color: "#4b5563",
          fontFamily: ImageGridHero_fontFamily,
          fontSize: "16px",
          fontWeight: 300,
          lineHeight: "24px",
          margin: "44px 0 0",
        }}
      >
        {description}
      </Text>
    </Section>
  );
  return (
    <Section style={{ backgroundColor, padding: "44px 0" }}>
      <Section style={{ textAlign: "center" }}>
        <Link href={logoHref}>
          <Img
            alt={logoAlt}
            src={logoSrc}
            width="165"
            style={{ display: "inline-block", maxWidth: "100%" }}
          />
        </Link>
      </Section>
      {imagesFirst ? (
        <>
          <ImageGridHero_Spacer height={44} />
          {gallery}
          {content}
        </>
      ) : (
        <>
          {content}
          <ImageGridHero_Spacer height={44} />
          {gallery}
        </>
      )}
      <ImageGridHero_Spacer height={44} />
      <Section style={{ textAlign: "center" }}>
        {ctaLabel && ctaHref ? (
          <Button
            align="center"
            height={44}
            href={ctaHref}
            width={166}
            style={{
              backgroundColor: buttonBackgroundColor,
              borderRadius: "8px",
              color: buttonTextColor,
              display: "inline-block",
              fontFamily: ImageGridHero_fontFamily,
              fontSize: "16px",
              fontWeight: 500,
              height: "auto",
              lineHeight: 1,
              padding: "14px 20px",
              textDecoration: "none",
              width: "auto",
            }}
          >
            <span style={{ marginRight: "8px" }}>{ctaLabel}</span>
            <Img
              alt=""
              src={emailAsset("icon-arrow-right.png")}
              width="12"
              style={{
                display: "inline-block",
                maxWidth: "100%",
                verticalAlign: "baseline",
              }}
            />
          </Button>
        ) : null}
      </Section>
    </Section>
  );
};

const ImageGridHero_HeroWithImageGrid = ({
  backgroundColor = "#fffffe",
  buttonBackgroundColor = "#4f46e5",
  buttonTextColor = "#fffffe",
  ctaHref = "https://example.com",
  ctaLabel = "Discover now",
  description = "A curated look at design, culture, and creativity in motion. From classics reborn to boundary-pushing silhouettes — see what's shaping the streets today.",
  eyebrow = "NEW ARRIVALS",
  heading = "Step into the hype",
  images = [],
  logoAlt = "emailcn",
  logoHref = "https://example.com",
  logoSrc = emailAsset("emailcn-logo.png"),
  pageBackgroundColor = "#f1f5f9",
  subheading = "The evolution of the sneaker",
  theme = defaultTheme,
  variant = "images-bottom",
}: ImageGridHero_HeroWithImageGridProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style
        dangerouslySetInnerHTML={{ __html: ImageGridHero_responsiveStyles }}
      />
    </EmailHead>
    <Preview>{`${heading} — ${subheading}`}</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{
          backgroundColor: pageBackgroundColor,
          fontFamily: ImageGridHero_fontFamily,
        }}
        className="text-fg m-0"
      >
        <Container
          className="hero-image-grid-container mx-auto max-w-[600px] w-[600px]"
          style={{
            backgroundColor,
          }}
        >
          <ImageGridHero_HeroWithImageGridSection
            backgroundColor={backgroundColor}
            buttonBackgroundColor={buttonBackgroundColor}
            buttonTextColor={buttonTextColor}
            ctaHref={ctaHref}
            ctaLabel={ctaLabel}
            description={description}
            eyebrow={eyebrow}
            heading={heading}
            images={images}
            logoAlt={logoAlt}
            logoHref={logoHref}
            logoSrc={logoSrc}
            pageBackgroundColor={pageBackgroundColor}
            subheading={subheading}
            variant={variant}
          />
        </Container>
      </Body>
    </EmailTailwind>
  </Html>
);

ImageGridHero_HeroWithImageGrid.PreviewProps = {
  backgroundColor: "#fffffe",
  buttonBackgroundColor: "#4f46e5",
  buttonTextColor: "#fffffe",
  ctaHref: "https://example.com",
  ctaLabel: "Discover now",
  description:
    "A curated look at design, culture, and creativity in motion. From classics reborn to boundary-pushing silhouettes — see what's shaping the streets today.",
  eyebrow: "NEW ARRIVALS",
  heading: "Step into the hype",
  images: [],
  logoAlt: "emailcn",
  logoHref: "https://example.com",
  logoSrc: emailAsset("emailcn-logo.png"),
  pageBackgroundColor: "#f1f5f9",
  subheading: "The evolution of the sneaker",
  theme: defaultTheme,
  variant: "images-bottom",
} satisfies ImageGridHero_HeroWithImageGridProps;

const __ImageGridHero = ImageGridHero_HeroWithImageGrid;

export interface HeroContent {
  eyebrow?: string;
  heading?: string;
  emphasis?: string;
  subheading?: string;
  description?: string;
  price?: string;
  actions?: {
    href: string;
    label: string;
  }[];
}

export interface HeroImage {
  src: string;
  alt?: string;
}

export interface HeroBrand {
  logo: HeroImage;
  href?: string;
}

export interface ImageGridHeroProps {
  theme?: Parameters<typeof __ImageGridHero>[0]["theme"];
  content?: HeroContent;
  images?: HeroImage[];
  brand?: HeroBrand;
  imagePosition?: "top" | "bottom";
  offset?: boolean;
}

export const ImageGridHero = ({
  theme,
  content,
  images,
  brand,
  imagePosition = "bottom",
  offset = false,
}: ImageGridHeroProps) => (
  <__ImageGridHero
    ctaHref={content?.actions?.[0]?.href}
    ctaLabel={content?.actions?.[0]?.label}
    description={content?.description}
    eyebrow={content?.eyebrow}
    heading={content?.heading}
    subheading={content?.subheading}
    images={images?.map((image) => ({ ...image, alt: image.alt ?? "" }))}
    logoAlt={brand?.logo.alt}
    logoHref={brand?.href}
    logoSrc={brand?.logo.src}
    theme={theme}
    variant={`${offset ? "offset-" : ""}images-${imagePosition}`}
  />
);

ImageGridHero.PreviewProps = {
  imagePosition: "bottom",
  offset: false,
} satisfies ImageGridHeroProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
